// minimal .sio exercising ONLY the converted binary-expr path (literal operands ->
// checker_check_expr_inplace recursion, binary_result_type, op_types, units, and the
// const-int zero-denominator div bridge). No Knowledge/Hyper needed to hit the hot path;
// a separate div-by-zero line exercises the eval_const_int leaf bridge.
fn main() -> i64 {
    let a: i64 = 2 + 3 * 4
    let b: bool = a < 100 && a > 0
    let c: i64 = a - 7
    if b { c } else { a }
}

fn id(x: i64) -> i64 {
    x
}

fn main() -> i64 {
    let a: i64 = id(7)
    let b: i64 = id(id(a))
    b
}
// Exercises ONLY the converted clean-TyFn path: id is a plain top-level fn
// (callee resolves to TyFn with fn_sig_id >= 0), nested call id(id(a)) forces
// checker_check_call_expr_inplace recursion through checker_check_opt_expr_inplace,
// and the three leaf bridges (check_call_args / check_callee_effects /
// release_call_arg_borrows) all run. No builtins, no index, no contest/witness,
// no multitest/hypothesis effects, no array-like callee => the checker_check_expr_mut
