// Field access whose RECEIVER stays entirely on the inline/*mut path:
// a string literal receiver routes through ExprStringLit (inline arm),
// never through the 12MB checker_check_expr_mut. The .foo access then
// hits the final else branch -> E012 (no struct/Knowledge type on a literal),
// exercising checker_check_field_access_inplace's receiver-recursion +
// checker_report_error_at_inplace path under the 8MB stack with no overflow.
fn main() -> i64 with IO, Mut, Panic, Div, Alloc {
    let t = "abc".foo
    0
}

// Exercises ONLY the converted method-call path (TyNamed found-method branch + args check
// + callee-effects + receiver via checker_check_opt_expr_inplace). No other expr kind on the
// hot path beyond already-converted IntLit and Ident-receiver. Run: souc --check@8MB this.sio
struct Counter {
    n: i64,
}

impl Counter {
    fn bump(self, by: i64) -> i64 {
        self.n + by
    }
}

fn main() -> i64 {
    let c = Counter { n: 1 }
    let r = c.bump(2)
    r
}

// --check@8MB gate input: a struct, an enum, and a fn that USES both.
// Deliberately contains ZERO of the 13 unconverted prelude kinds (no impl/
// trait/effect/policy/etc), so the collect pass exercises ONLY the new
// in-place ItemStruct/ItemEnum arms and never the by-value bridge fallback.

struct Point {
    x: i64,
    y: i64,
}

enum Shape {
    Dot,
    Seg { a: Point, b: Point },
}

fn area(p: Point, s: Shape) -> i64 {
    let dx = p.x + p.y
    match s {
        Dot => dx
        Seg { a, b } => a.x + b.y + dx
    }
}

fn main() -> i64 {
    let p = Point { x: 3, y: 4 }
    let s = Shape::Dot
    area(p, s)
}
